//! TypeScript declarations derived from the public JSON presentation contracts.
use ts_rs::{Config, TS};

pub fn typescript() -> String {
    let config = Config::new().with_large_int("number");
    macro_rules! declarations {
        ($($ty:ty),+ $(,)?) => { vec![$(format!("export {}", <$ty>::decl(&config))),+] };
    }
    let declarations = declarations![
        crate::private_sync::SynchronizedAccount,
        crate::private_sync::LocalUsageSnapshot,
        crate::private_sync::LocalUsageDay,
        crate::private_sync::PrivateEvent,
        crate::private_sync::PrivateObservation,
        crate::private_sync::PrivateStoredObservation,
        crate::private_sync::PrivateRecentPage,
        crate::HistorySample,
        crate::UsageRecord,
        fabrials_core::AccountScope,
        fabrials_core::Availability,
        fabrials_core::Freshness,
        fabrials_core::Observation<()>,
        fabrials_core::ResetCredit,
        fabrials_core::ResetInventory,
        fabrials_core::CreditBalance,
        fabrials_core::Capabilities,
        fabrials_core::ProviderDescriptor,
        fabrials_core::SharingConsent,
        fabrials_core::migration::CredentialKind,
        fabrials_core::migration::MigrationCandidate,
        fabrials_core::migration::MigrationSelection,
        fabrials_core::migration::MigrationAction,
        fabrials_core::migration::MigrationItem,
        fabrials_core::migration::MigrationReview,
        fabrials_core::migration::MigrationDirection,
        fabrials_core::migration::MigrationInvitation,
        fabrials_core::migration::MigrationSessionView,
        crate::MetricKind,
        crate::ProgressFormat,
        crate::BarChartPoint,
        crate::MetricLine,
        crate::ProviderOutput,
    ];
    format!("// Generated by fabrials-model; do not edit.\n// JSON timestamps use JavaScript numbers, not bigint.\n\n{}\n", declarations.join("\n\n"))
}

#[cfg(test)]
mod tests {
    #[test]
    fn checked_in_types_match_rust_contracts() {
        assert_eq!(super::typescript(), include_str!("../bindings/contracts.ts"),
            "Run the contracts example to regenerate bindings/contracts.ts, then sync shared sources");
    }
}
